import { useState, useEffect, useCallback, memo, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, ChevronRight, Play, Info, Star, Calendar } from 'lucide-react';
import { img, getDetail } from '../lib/tmdb';
import { useSettings } from '../contexts/SettingsContext';

interface HeroSliderProps {
  mediaItems: Array<{
    id: number;
    title?: string;
    name?: string;
    poster_path: string | null;
    backdrop_path: string | null;
    overview?: string;
    vote_average?: number;
    release_date?: string;
    first_air_date?: string;
    media_type?: 'movie' | 'tv';
  }>;
}

// Detail cache to prevent redundant API calls
const detailCache = new Map<string, any>();

function HeroSliderInner({ mediaItems }: HeroSliderProps) {
  const navigate = useNavigate();
  const { settings } = useSettings();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [detail, setDetail] = useState<any>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const detailLoading = useRef(false);

  const current = mediaItems[currentIndex];

  // Auto-play with O(1) cleanup
  const startAutoPlay = useCallback(() => {
    if (intervalRef.current) clearInterval(intervalRef.current);
    intervalRef.current = setInterval(() => {
      setCurrentIndex(prev => (prev + 1) % mediaItems.length);
    }, 7000);
  }, [mediaItems.length]);

  useEffect(() => {
    startAutoPlay();
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [startAutoPlay]);

  // Reset on index change
  useEffect(() => {
    setDetail(null);
    setIsTransitioning(true);
    const timer = setTimeout(() => setIsTransitioning(false), 500);
    return () => clearTimeout(timer);
  }, [currentIndex]);

  // Load detail data with cache
  useEffect(() => {
    if (!current) return;
    const cacheKey = `${current.media_type || 'movie'}-${current.id}`;
    
    // Return cached detail if available
    if (detailCache.has(cacheKey)) {
      setDetail(detailCache.get(cacheKey));
      return;
    }

    if (detailLoading.current) return;
    detailLoading.current = true;
    
    const loadDetail = async () => {
      try {
        const data = await getDetail(current.media_type || 'movie', current.id);
        detailCache.set(cacheKey, data);
        setDetail(data);
      } catch {
        setDetail(null);
      } finally {
        detailLoading.current = false;
      }
    };
    loadDetail();
  }, [current]);

  const goTo = useCallback((index: number) => {
    if (isTransitioning) return;
    setIsTransitioning(true);
    setCurrentIndex(index);
  }, [isTransitioning]);

  const goNext = useCallback(() => {
    goTo((currentIndex + 1) % mediaItems.length);
  }, [currentIndex, mediaItems.length]);

  const goPrev = useCallback(() => {
    goTo((currentIndex - 1 + mediaItems.length) % mediaItems.length);
  }, [currentIndex, mediaItems.length]);

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'ArrowRight') goNext();
    if (e.key === 'ArrowLeft') goPrev();
  }, [goNext, goPrev]);

  useEffect(() => {
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  if (!current || mediaItems.length === 0) return null;

  // Memoized computed values
  const { backdrop, title, year, rating, overview, type } = useMemo(() => ({
    backdrop: current.backdrop_path
      ? img(current.backdrop_path, 'w1280')
      : current.poster_path
        ? img(current.poster_path, 'w1280')
        : null,
    title: current.title || current.name || 'Untitled',
    year: (current.release_date || current.first_air_date || '').slice(0, 4),
    rating: current.vote_average?.toFixed(1) || 'N/A',
    overview: detail?.overview || current.overview || 'No description available.',
    type: current.media_type || 'movie',
  }), [current, detail]);

  return (
    <div 
      className="relative h-[70vh] sm:h-[80vh] md:h-[85vh] overflow-hidden group/slider"
      style={{ contain: 'style layout' }}
    >
      {/* Background */}
      {backdrop && (
        <div className="absolute inset-0">
          <img
            src={backdrop}
            alt=""
            className={`w-full h-full object-cover transition-all duration-700 ${
              isTransitioning ? 'scale-110 blur-sm' : 'scale-100 blur-0'
            }`}
            loading={currentIndex === 0 ? 'eager' : 'lazy'}
            style={{ contain: 'strict', transform: 'translateZ(0)' }}
          />
          {/* Gradient overlays */}
          <div className="absolute inset-0 bg-gradient-to-r from-[#0a0a0f] via-[#0a0a0f]/60 to-transparent" />
          <div className="absolute inset-0 bg-gradient-to-t from-[#0a0a0f] via-[#0a0a0f]/30 to-transparent" />
          <div className="absolute bottom-0 left-0 right-0 h-32 bg-gradient-to-t from-[#0a0a0f] to-transparent" />
        </div>
      )}

      {/* Content */}
      <div className={`relative h-full max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 md:px-12 flex items-end transition-opacity duration-500 ${
        isTransitioning ? 'opacity-0' : 'opacity-100'
      }`}>
        <div className="pb-16 sm:pb-20 md:pb-24 w-full">
          {/* Title */}
          <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-black text-white leading-tight mb-3 drop-shadow-2xl">
            {title}
          </h1>

          {/* Meta */}
          <div className="flex flex-wrap items-center gap-3 mb-4">
            {year && (
              <span className="flex items-center gap-1.5 text-white/70 text-sm font-medium">
                <Calendar size={14} className="text-emerald-400" />
                {year}
              </span>
            )}
            <span className="flex items-center gap-1.5 text-white/70 text-sm font-medium">
              <Star size={14} className="text-amber-400" fill="currentColor" />
              {rating}
            </span>
            <span className="px-2.5 py-0.5 bg-emerald-500/20 border border-emerald-500/30 rounded text-xs font-bold text-emerald-400 uppercase">
              {type}
            </span>
          </div>

          {/* Overview */}
          <p className="text-white/70 text-sm sm:text-base max-w-2xl mb-6 leading-relaxed line-clamp-3">
            {overview}
          </p>

          {/* Buttons */}
          <div className="flex flex-wrap items-center gap-3">
            <button
              onClick={() => navigate(`/${type}/${current.id}`)}
              className="flex items-center gap-2.5 px-6 sm:px-7 py-3 bg-emerald-500 hover:bg-emerald-400 text-white rounded-xl transition-all text-sm sm:text-base font-bold shadow-xl shadow-emerald-500/30 hover:shadow-emerald-500/50 hover:scale-105 active:scale-95"
              style={{ contain: 'style layout' }}
            >
              <Play size={20} fill="white" />
              Watch Now
            </button>
            <button
              onClick={() => navigate(`/${type}/${current.id}`)}
              className="flex items-center gap-2 px-5 py-3 bg-white/10 hover:bg-white/20 text-white rounded-xl transition-all text-sm font-semibold border border-white/10 hover:border-white/20 backdrop-blur-sm"
              style={{ contain: 'style layout' }}
            >
              <Info size={18} />
              More Info
            </button>
          </div>
        </div>
      </div>

      {/* Navigation arrows */}
      <button
        onClick={goPrev}
        className="absolute left-3 sm:left-5 top-1/2 -translate-y-1/2 p-2.5 sm:p-3 bg-black/40 hover:bg-black/60 backdrop-blur-sm text-white rounded-full transition-all opacity-0 group-hover/slider:opacity-100 hover:scale-110 active:scale-95"
        aria-label="Previous slide"
        style={{ contain: 'style layout' }}
      >
        <ChevronLeft size={24} />
      </button>
      <button
        onClick={goNext}
        className="absolute right-3 sm:right-5 top-1/2 -translate-y-1/2 p-2.5 sm:p-3 bg-black/40 hover:bg-black/60 backdrop-blur-sm text-white rounded-full transition-all opacity-0 group-hover/slider:opacity-100 hover:scale-110 active:scale-95"
        aria-label="Next slide"
        style={{ contain: 'style layout' }}
      >
        <ChevronRight size={24} />
      </button>

      {/* Dots indicator - memoized */}
      <div className="absolute bottom-4 sm:bottom-6 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
        {mediaItems.map((_, index) => (
          <button
            key={index}
            onClick={() => goTo(index)}
            className={`transition-all rounded-full ${
              index === currentIndex
                ? 'w-8 h-2 bg-emerald-400'
                : 'w-2 h-2 bg-white/40 hover:bg-white/60'
            }`}
            aria-label={`Go to slide ${index + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

export default memo(HeroSliderInner);