import { useState, useEffect, useCallback, useRef, memo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, ArrowRight } from 'lucide-react';
import { getTrending, getPopular, getOnTheAir, getAiringToday, img, searchMulti } from '../lib/tmdb';
import type { MediaItem } from '../lib/tmdb';
import HeroSlider from '../components/HeroSlider';
import MediaRow from '../components/MediaRow';
import { RowSkeleton } from '../components/Spinner';
import { useHistory } from '../contexts/HistoryContext';

// Preload images in batch for better performance
const preloadImages = (images: string[]): void => {
  const toPreload = images.filter(src => src.length > 0);
  if (toPreload.length === 0) return;
  const fragment = toPreload.slice(0, 10);
  fragment.forEach(src => {
    const imgElement = new Image();
    imgElement.src = src;
  });
};

function HomeInner() {
  const navigate = useNavigate();
  const { getRecentViews } = useHistory();
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState('');
  const [searchResults, setSearchResults] = useState<MediaItem[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [trending, setTrending] = useState<MediaItem[]>([]);
  const [popularMovies, setPopularMovies] = useState<MediaItem[]>([]);
  const [popularTV, setPopularTV] = useState<MediaItem[]>([]);
  const [onTheAirShows, setOnTheAirShows] = useState<MediaItem[]>([]);
  const [airingToday, setAiringToday] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      try {
        const [trendingData, popularMoviesData, onTheAirData, airingTodayData, popularTVData] = await Promise.all([
          getTrending('all', 'week'),
          getPopular('movie'),
          getOnTheAir(),
          getAiringToday(),
          getPopular('tv'),
        ]);

        setTrending(trendingData.results || []);
        setPopularMovies(popularMoviesData.results || []);
        setPopularTV(popularTVData.results || []);
        setOnTheAirShows(onTheAirData.results || []);
        setAiringToday(airingTodayData.results || []);

        // Preload images for trending items (batch)
        const backdropUrls = (trendingData.results || [])
          .slice(0, 5)
          .map((item: MediaItem) => item.backdrop_path)
          .filter(Boolean)
          .map(path => img(path!, 'w1280'));
        preloadImages(backdropUrls);
      } catch (error) {
        console.error('Failed to load home data:', error);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, []);

  useEffect(() => {
    if (showSearchResults && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [showSearchResults]);

  const performSearch = useCallback(async (searchQuery: string) => {
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    try {
      const data = await searchMulti(searchQuery, '1');
      const filtered = (data.results ?? []).filter(
        (r: MediaItem) => r.media_type === 'movie' || r.media_type === 'tv'
      );
      setSearchResults(filtered.slice(0, 30));
    } catch {
      setSearchResults([]);
    } finally {
      setIsSearching(false);
    }
  }, []);

  const handleSearch = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      performSearch(query.trim());
      setShowSearchResults(true);
    }
  }, [query, performSearch]);

  const clearSearch = useCallback(() => {
    setQuery('');
    setSearchResults([]);
    setShowSearchResults(false);
  }, []);

  const goSearch = useCallback((title: string) => {
    setQuery(title);
    performSearch(title);
    setShowSearchResults(true);
  }, [performSearch]);

  const recentViews = getRecentViews(10);
  const recentViewItems: MediaItem[] = recentViews.map(r => ({
    id: r.id,
    title: r.title,
    poster_path: r.poster_path,
    backdrop_path: null,
    overview: '',
    vote_average: 0,
    media_type: r.type as 'movie' | 'tv',
  }));

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0a0a0f]">
        <div className="pt-16">
          <RowSkeleton count={8} />
          <RowSkeleton count={8} />
          <RowSkeleton count={8} />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0a0a0f]">
      {showSearchResults ? (
        <div className="pt-20 page-transition">
          <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-8">
            <div className="mb-8">
              <div className="flex items-center gap-4 mb-4">
                <button
                  onClick={clearSearch}
                  className="p-2 text-white/50 hover:text-white hover:bg-white/10 rounded-lg transition-all"
                  aria-label="Back to home"
                >
                  <ArrowRight size={20} className="rotate-180" />
                </button>
                <form onSubmit={handleSearch} className="flex-1">
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-white/30" size={18} />
                    <input
                      ref={searchInputRef}
                      type="text"
                      value={query}
                      onChange={e => setQuery(e.target.value)}
                      placeholder="Search for movies, TV shows..."
                      className="w-full bg-white/5 border border-white/10 text-white placeholder-white/30 rounded-xl pl-12 pr-4 py-3 text-sm focus:outline-none focus:border-white/30 transition-all"
                    />
                  </div>
                </form>
              </div>
              <h1 className="text-2xl font-bold text-white">
                {isSearching ? 'Searching...' : `Results for "${query}"`}
              </h1>
              <p className="text-white/40 text-sm mt-1">
                {isSearching ? 'Please wait' : `${searchResults.length} results found`}
              </p>
            </div>

            {isSearching ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8 gap-2 sm:gap-3">
                {Array.from({ length: 18 }).map((_, i) => (
                  <div key={i} className="aspect-[2/3] rounded-xl bg-white/5 animate-pulse" />
                ))}
              </div>
            ) : searchResults.length > 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8 gap-2 sm:gap-3">
                {searchResults.map(item => {
                  const type = (item.media_type || 'movie') as string;
                  const title = item.title || item.name || '';
                  const year = (item.release_date || item.first_air_date || '').slice(0, 4);
                  const poster = item.poster_path ? img(item.poster_path, 'w342') : null;

                  return (
                    <div
                      key={item.id}
                      className="group relative flex flex-col rounded-xl overflow-hidden bg-white/5 border border-white/5 hover:border-white/20 transition-all duration-300 hover:shadow-xl hover:-translate-y-1 cursor-pointer card-contain"
                      onClick={() => navigate(`/${type}/${item.id}`)}
                    >
                      <div className="relative aspect-[2/3] overflow-hidden bg-white/5">
                        {poster ? (
                          <img
                            src={poster}
                            alt={title}
                            loading="lazy"
                            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                          />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-white/20 bg-gradient-to-br from-white/5 to-white/10">
                            <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                              <rect x="2" y="2" width="20" height="20" rx="2.18" />
                              <line x1="7" y1="2" x2="7" y2="22" />
                              <line x1="17" y1="2" x2="17" y2="22" />
                              <line x1="2" y1="12" x2="22" y2="12" />
                            </svg>
                          </div>
                        )}
                        <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent" />
                        <div className="absolute bottom-2 left-2 px-2 py-0.5 bg-white/20 backdrop-blur-sm rounded-md">
                          <span className="text-white text-[10px] font-bold uppercase">{type}</span>
                        </div>
                      </div>
                      <div className="p-3">
                        <p className="text-white text-sm font-medium leading-tight line-clamp-1 group-hover:text-emerald-400 transition-colors">
                          {title}
                        </p>
                        {year && <span className="text-white/40 text-xs">{year}</span>}
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="text-center py-24">
                <Search size={56} className="mx-auto text-white/10 mb-5" />
                <p className="text-white/30 text-lg font-medium">No results found</p>
                <p className="text-white/20 text-sm mt-2">Try searching for a different title</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div>
          <HeroSlider />
          <div className="relative -mt-8 z-10 max-w-2xl mx-auto px-4">
            <form onSubmit={handleSearch} className="glass rounded-2xl p-2 flex items-center gap-2 animate-slide-up">
              <Search className="text-white/30 ml-3" size={20} />
              <input
                type="text"
                value={query}
                onChange={e => setQuery(e.target.value)}
                placeholder="Search for movies, TV shows..."
                className="flex-1 bg-transparent text-white placeholder-white/40 py-3 px-2 focus:outline-none text-base"
              />
            </form>
          </div>
          <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6">
            {recentViewItems.length > 0 && (
              <MediaRow
                title="Continue Watching"
                items={recentViewItems}
                mediaType={recentViewItems[0]?.media_type}
                showProgress
              />
            )}
            {trending.length > 0 && (
              <MediaRow
                title="🔥 Trending This Week"
                items={trending.slice(0, 20)}
                mediaType="movie"
                viewAllLink="/movies"
              />
            )}
            {popularMovies.length > 0 && (
              <MediaRow
                title="Popular Movies"
                items={popularMovies.slice(0, 20)}
                mediaType="movie"
                viewAllLink="/movies"
              />
            )}
            {popularTV.length > 0 && (
              <MediaRow
                title="Popular TV Shows"
                items={popularTV.slice(0, 20)}
                mediaType="tv"
                viewAllLink="/tv"
              />
            )}
            {airingToday.length > 0 && (
              <MediaRow
                title="Airing Today"
                items={airingToday.slice(0, 15)}
                mediaType="tv"
                viewAllLink="/tv"
              />
            )}
            {onTheAirShows.length > 0 && (
              <MediaRow
                title="Coming Soon"
                items={onTheAirShows.slice(0, 15)}
                mediaType="tv"
                viewAllLink="/tv"
              />
            )}
            <div className="mt-12 mb-8 text-center">
              <h3 className="text-white/40 text-sm mb-4">Popular Searches</h3>
              <div className="flex flex-wrap items-center justify-center gap-2">
                {['Oppenheimer', 'The Last of Us', 'Attack on Titan', 'Stranger Things', 'Dune', 'Breaking Bad', 'The Batman', 'Wednesday'].map(term => (
                  <button
                    key={term}
                    onClick={() => goSearch(term)}
                    className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 hover:border-white/20 text-white/50 hover:text-white/80 rounded-full text-sm transition-all"
                  >
                    {term}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default memo(HomeInner);